import threading
import sys

# Keep generated bytecode out of the app source directories.
sys.dont_write_bytecode = True

from fastapi import HTTPException
from arduino.app_utils import App, Bridge
from arduino.app_bricks.web_ui import WebUI
from controller import Controller
from gpu_telemetry import CPU_DISABLED, GpuTelemetry
from walk_lab import WalkLab, walk_command

# Bound GIL handoff latency between the 100 Hz receiver, policy and WebUI.
sys.setswitchinterval(0.001)
controller = Controller(Bridge)
gpu = GpuTelemetry(Bridge)
walk_lab = WalkLab(lambda: controller.loop_missed)
try:
    ui = WebUI(port=9527, cors_origins='')
except TypeError as exc:
    if "unexpected keyword argument 'cors_origins'" not in str(exc):
        raise
    # App Bricks 0.5.0 lacks the option and otherwise allows every Socket.IO
    # origin. Preserve same-origin checks on factory images.
    ui = WebUI(port=9527)
    ui.app.sio.eio.cors_allowed_origins = None
Bridge.provide('duck_state', controller.receive)
Bridge.provide('duck_diagnostics', controller.receive_diagnostics)
Bridge.provide('duck_voltage', controller.receive_voltage)
Bridge.provide('duck_boot_pd', controller.receive_boot_pd)
Bridge.provide('duck_raw', controller.receive_raw)
Bridge.provide('duck_servo_reply', controller.receive_servo_reply)
Bridge.provide('duck_cal_reply', controller.receive_cal_reply)

def mode(body: dict):
    try: return controller.set_mode(body['mode'])
    except (KeyError, ValueError) as exc: raise HTTPException(400, str(exc))

def roller(body: dict):
    try: return controller.set_roller_mode(body['enabled'])
    except (KeyError, ValueError) as exc: raise HTTPException(400, str(exc))

def heading_hold(body: dict):
    try: return controller.set_heading_hold(body['enabled'])
    except (KeyError, ValueError) as exc: raise HTTPException(400, str(exc))

def command(body: dict):
    try: return controller.command(**body)
    except (TypeError, ValueError) as exc: raise HTTPException(400, str(exc))

def filtering(body: dict):
    try:
        leg, head = controller.set_action_alphas(**body)
        return {'leg':leg,'head':head}
    except (TypeError, ValueError) as exc: raise HTTPException(400, str(exc))

def imu_filtering(body: dict):
    try: return controller.set_imu_filters(**body)
    except (TypeError, ValueError) as exc: raise HTTPException(400, str(exc))

def imu_calibration(body: dict):
    try:
        action = body.get('action', 'start')
        if action == 'start': return controller.start_imu_calibration()
        if action == 'reset': return controller.reset_imu_calibration()
        raise ValueError('unknown IMU calibration action')
    except (TypeError, ValueError) as exc: raise HTTPException(400, str(exc))

def action_scale(body: dict):
    try: return controller.set_action_scale(**body)
    except (TypeError, ValueError) as exc: raise HTTPException(400, str(exc))

def pick(_body: dict = None):
    try: return controller.start_pick()
    except ValueError as exc: raise HTTPException(400, str(exc))

def roulade(_body: dict = None):
    try: return controller.start_roulade()
    except ValueError as exc: raise HTTPException(400, str(exc))

def sitstand(body: dict):
    try: return controller.set_sitstand(body['action'])
    except (KeyError, TypeError, ValueError) as exc: raise HTTPException(400, str(exc))

def right_kick(_body: dict = None):
    try: return controller.start_kick('right')
    except ValueError as exc: raise HTTPException(400, str(exc))

def left_kick(_body: dict = None):
    try: return controller.start_kick('left')
    except ValueError as exc: raise HTTPException(400, str(exc))

def cal_enter(_body: dict = None):
    try: return controller.set_mode('calibrate')
    except ValueError as exc: raise HTTPException(400, str(exc))

def cal_exit(_body: dict = None):
    try: return controller.set_mode('shadow')
    except ValueError as exc: raise HTTPException(400, str(exc))

def cal_heartbeat(_body: dict = None):
    try: return controller.cal_heartbeat()
    except ValueError as exc: raise HTTPException(400, str(exc))

def cal_center(body: dict):
    try: return controller.cal_center(body['index'])
    except (KeyError, TypeError, ValueError) as exc: raise HTTPException(400, str(exc))

def servo_enter(_body: dict = None):
    try: return controller.set_mode('servo_debug')
    except ValueError as exc: raise HTTPException(400, str(exc))

def servo_exit(_body: dict = None):
    try: return controller.set_mode('shadow')
    except ValueError as exc: raise HTTPException(400, str(exc))

def servo_action(body: dict):
    try:
        return controller.servo_op(
            body['action'], body.get('target_id'),
            new_id=body.get('new_id'), kp=body.get('kp', 5), kd=body.get('kd', 20),
            protection_enabled=body.get('protection_enabled', True), current_a=body.get('current_a', 1.0))
    except (KeyError, TypeError, ValueError) as exc:
        raise HTTPException(400, str(exc))

def status():
    sample = dict(gpu.latest)
    cpu = sample.pop('cpu', CPU_DISABLED)
    return dict(controller.status(), gpu=sample, cpu=cpu)

def walk_start(body: dict):
    try:
        vx, yaw, arena = walk_command(body)
    except ValueError as exc:
        raise HTTPException(400, str(exc))
    hardware = controller.status()
    if hardware.get('enabled', False) or hardware['mode'] not in ('off', 'shadow'):
        raise HTTPException(409, 'Put the hardware in Shadow or Off before starting a rollout.')
    try:
        return walk_lab.start(vx, yaw, arena)
    except RuntimeError as exc:
        raise HTTPException(409, str(exc))

def walk_stop(_body: dict):
    return walk_lab.stop()

ui.expose_api('GET', '/api/status', status)
ui.expose_api('GET', '/api/lab/walk', walk_lab.status)
ui.expose_api('POST', '/api/lab/walk/start', walk_start)
ui.expose_api('POST', '/api/lab/walk/stop', walk_stop)
ui.expose_api('GET', '/api/gpu', lambda: {key: value for key, value in gpu.latest.items() if key != 'cpu'})
ui.expose_api('POST', '/api/mode', mode)
ui.expose_api('POST', '/api/roller', roller)
ui.expose_api('POST', '/api/heading-hold', heading_hold)
ui.expose_api('POST', '/api/command', command)
ui.expose_api('POST', '/api/filter', filtering)
ui.expose_api('POST', '/api/imu-filter', imu_filtering)
ui.expose_api('POST', '/api/imu-calibration', imu_calibration)
ui.expose_api('POST', '/api/action-scale', action_scale)
ui.expose_api('POST', '/api/pick', pick)
ui.expose_api('POST', '/api/roulade', roulade)
ui.expose_api('GET', '/api/roulade-timing', controller.roulade_timing)
ui.expose_api('POST', '/api/sitstand', sitstand)
ui.expose_api('POST', '/api/right_kick', right_kick)
ui.expose_api('POST', '/api/left_kick', left_kick)
ui.expose_api('POST', '/api/cal/enter', cal_enter)
ui.expose_api('POST', '/api/cal/exit', cal_exit)
ui.expose_api('POST', '/api/cal/heartbeat', cal_heartbeat)
ui.expose_api('POST', '/api/cal/center', cal_center)
ui.expose_api('POST', '/api/servo/enter', servo_enter)
ui.expose_api('POST', '/api/servo/exit', servo_exit)
ui.expose_api('POST', '/api/servo', servo_action)
worker = threading.Thread(target=controller.run, name='policy50', daemon=True)
worker.start()
gpu.start()
try:
    App.run()
finally:
    walk_lab.stop()
    controller.stop()
    gpu.stop()
    worker.join(timeout=2)
